INSERT INTO `indikator_skor` VALUES (1,1,'I1','Kejelasan Pengelolaan & Rencana Tindak Lanjut\nCara periksa: Apakah pelaksanaan kerja sama telah memiliki penanggung jawab yang jelas, rencana tindak lanjut yang dapat dilaksanakan, dan mekanisme koordinasi untuk memastikan tindak lanjut tersebut berjalan?',10,'Baseline awal terverifikasi',NULL,NULL,'BELUM DITELAAH',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 03:43:07'),(2,1,'I2','Implementasi / Tindak Lanjut\nCara periksa: Apakah kerja sama telah ditindaklanjuti melalui kegiatan atau langkah implementasi yang relevan dan dapat dibuktikan?',15,'Baseline awal terverifikasi',NULL,NULL,'BELUM DITELAAH',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 03:43:07'),(3,1,'I3','Output\nCara periksa: Apakah kegiatan menghasilkan produk/hasil langsung yang seharusnya dicapai?',15,'Baseline awal terverifikasi',NULL,NULL,'BELUM DITELAAH',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 03:43:07'),(4,1,'I4','Outcome\nCara periksa: Apakah output mulai memberi perubahan/manfaat kepada sasaran, proses, layanan, atau organisasi?',20,'Baseline awal terverifikasi',NULL,NULL,'BELUM DITELAAH',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 03:43:07'),(5,1,'I5','Kontribusi / Dampak\nCara periksa: Apakah hasil kerja sama berkontribusi terhadap sasaran kinerja organisasi dan/atau pelayanan hukum?',20,'Baseline awal terverifikasi',NULL,NULL,'BELUM DITELAAH',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 03:43:07'),(6,1,'I6','Evidence & Data\nCara periksa: Apakah data/evidence cukup, mutakhir, dan dapat ditelusuri ke sumbernya?',10,'Baseline awal terverifikasi',NULL,NULL,'BELUM DITELAAH',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 03:43:07'),(7,1,'I7','Risiko & Keberlanjutan\nCara periksa: Apakah risiko utama ditangani dan ada kondisi yang mendukung keberlanjutan manfaat?',10,'Baseline awal terverifikasi',NULL,NULL,'BELUM DITELAAH',NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-23 03:43:07'),(8,2,'I1','Kejelasan Pengelolaan & Rencana Tindak Lanjut\nCara periksa: Apakah pelaksanaan k