INSERT INTO `rencana_kerja` VALUES (1,4,'Rencana Kerja Fasilitasi dan Pendaftaran Kekayaan Intelektual Daerah Bintan','Inventarisasi potensi KI komunal, pendampingan pendaftaran merk UMKM binaan, dan sosialisasi hukum','Meningkatkan kesadaran hukum dan jumlah permohonan pendaftaran kekayaan intelektual di Kabupaten Bintan','2026-07-01','2027-06-30','Disetujui','Rencana kerja disetujui pimpinan; tindaklanjuti dan laporkan perkembangan secara berkala',NULL,'2026-09-23 03:51:03'),(2,16,'Rencana Kerja Fasilitasi Sentra Riset Hukum Maritim & Pos Bantuan Hukum Masyarakat Pesisir','Penyuluhan hukum, riset kebijakan maritim, dan klinik konsultasi hukum keliling','Mendekatkan akses keadilan dan pendampingan hukum pro-bono bagi masyarakat nelayan pesisir Kepulauan Riau','2026-10-01','2029-09-30','Disetujui','Disetujui otomatis melalui kelayakan Gate 0',NULL,'2026-09-23 03:55:13'),(3,17,'Rencana Kerja Inkubasi Paten dan Desain Industri Kampus Vokasi','','Mendorong hilirisasi riset terapan kampus vokasi ke pendaftaran paten resmi','0000-00-00','0000-00-00','Disetujui','Disetujui otomatis melalui kelayakan Gate 0',NULL,'2026-09-23 04:55:30'),(4,18,'Rencana Kerja Penguatan Literasi Hukum dan Layanan Terpadu Desa Sadar Hukum','Pelatihan paralegal dan sosialisasi peraturan','Membentuk desa binaan sadar hukum di pesisir','2027-01-01','2030-12-31','Disetujui','Disetujui otomatis melalui kelayakan Gate 0',NULL,'2026-09-23 05:21:55'),(5,2,'Integrasi Materi Pembelajaran E-Book & Modul Literasi Hukum pada BESTI Learning Hub','Integrasi e-book/modul literasi digital, edukasi hukum, kesadaran hukum, dan kekayaan intelektual','Meningkatkan literasi hukum dan pencegahan narkoba melalui platform digital','2026-09-01','2027-08-31','Disetujui','Disetujui berdasarkan tindak lanjut PKS BNN Kepri',NULL,'2026-09-23 16:46:08'),(6,2,'Kolaborasi Konten Edukasi Hukum & Pencegahan Narkoba (Podcast & Live Streaming)','Podcast bersama, webinar edukasi hukum, dan kampanye publik terpadu','Penyebarluasan informasi hukum dan bahaya narkoba bagi generasi muda Kepri','2026-10-01','2027-03-31','Disetujui','Sesuai kesepakatan rapat penguatan PIC',NULL,'2026-09-23 16:46:08'),(7,8,'Fasilitasi dan Pendampingan Pengurusan Kekayaan Intelektual Produk Hilirisasi Kampus Vokasi','Pemeriksaan substantif awal, pendampingan penyusunan spesifikasi paten, koreksi dokumen penolakan','Percepatan pendaftaran dan perolehan granted paten produk inovasi Polibatam','2026-10-01','2026-12-31','Disetujui','Usulan prioritas Sentra HKI Polibatam',NULL,'2026-09-23 16:46:08'),(8,8,'Pendampingan Teknis dan Lisensi Komersialisasi Kekayaan Intelektual Granted','Workshop lisensi, drafting perjanjian royalti, pendampingan komersialisasi ke industri','Menjadikan KI kampus memiliki nilai ekonomi dan daya serap industri','2026-11-01','2027-02-28','Disetujui','Mendukung program Merdeka Belajar Kampus Berdampak',NULL,'2026-09-23 16:46:08'),(9,9,'Pembentukan dan Penguatan Sentra Kekayaan Intelektual (Sentra KI) STAI/IAI Natuna','Penetapan struktur organisasi, tata kerja, sosialisasi dosen/mahasiswa, klinik pendaftaran','Membangun ekosistem perlindungan KI di wilayah perbatasan utara Natuna','2026-09-15','2027-09-14','Disetujui','Tindak lanjut MoU penguatan Tri Dharma wilayah perbatasan',NULL,'2026-09-23 16:46:08'),(10,9,'Klinik dan Fasilitasi Pendaftaran Hak Cipta & Merek Berbasis Khazanah Melayu Natuna','Inventarisasi karya buku, modul, karya budaya, dan merek produk lokal Natuna','Perlindungan hukum atas karya intelektual dan kekayaan komunal Natuna','2026-11-01','2026-12-31','Disetujui','Prioritas pelindungan budaya perbatasan',NULL,'2026-09-23 16:46:08'),(11,5,'Peningkatan Literasi Hukum dan Penguatan Tri Dharma Perguruan Tinggi Perbatasan','Penyuluhan hukum sivitas akademika, klinik konsultasi hukum, dan pembinaan desa sadar hukum','Mewujudkan kesadaran hukum masyarakat kampus dan perbatasan Bintan-Tanjungpinang','2026-09-01','2027-08-31','Disetujui','Kesepakatan bersama STAIN SAR Kepri',NULL,'2026-09-23 16:46:08'),(12,11,'Sosialisasi dan Klinik Pengajuan Paten Sederhana Sivitas Akademika','Bimbingan teknis drafting paten sederhana, inventarisasi invensi dosen dan mahasiswa','Peningkatan jumlah permohonan paten terdaftar dari kampus Politeknik Bintan Cakrawala','2026-10-01','2026-12-31','Disetujui','Tindak lanjut rapat penguatan Sentra KI',NULL,'2026-09-23 16:46:08'),(13,13,'Kuliah Pakar dan Pembentukan Pusat Konsultasi Layanan Hukum Terpadu','Kuliah umum berkala oleh narasumber Kanwil, pos aduan konsultasi hukum dan pendaftaran hak cipta','Edukasi hukum mahasiswa dan masyarakat sekitar kampus Batam','2026-09-01','2027-08-31','Disetujui','Sesuai usulan stakeholder Universitas Ibnu Sina',NULL,'2026-09-23 16:46:08'),(14,1,'Pelindungan dan Inventarisasi Kekayaan Intelektual Komunal Wastra dan Kriya Kepri','Pendataan motif batik/tenun Kepri, pendaftaran hak cipta dan merek kolektif pengrajin','Pemberdayaan ekonomi pengrajin lokal melalui kepastian hukum hak kekayaan intelektual','2025-06-01','2026-05-31','Disetujui','Implementasi PKS Dekranasda 2025-2030',NULL,'2026-09-23 16:46:08'),(15,3,'Pelayanan Hukum Terpadu dan Pembinaan Kelurahan Sadar Hukum Kota Tanjungpinang','Konsultasi hukum gratis, sosialisasi peraturan daerah, mediasi non-litigasi tingkat kelurahan','Meningkatkan kesadaran hukum masyarakat ibukota provinsi','2025-05-01','2026-04-30','Disetujui','Nota Kesepakatan Pemda Tanjungpinang',NULL,'2026-09-23 16:46:08'),(16,6,'Klinik Advokasi Hukum Nelayan Pesisir dan Sentra Riset Hukum Maritim','Konsultasi hukum keliling pulau, riset regulasi kelautan dan perikanan, pengabdian masyarakat','Mendekatkan keadilan hukum bagi nelayan tradisional Kepulauan Riau','2025-10-01','2026-09-30','Disetujui','Nota Kesepahaman UMRAH',NULL,'2026-09-23 16:46:08');
